head.script:
scwin.onpageload = function () {
    var cptIbxName = $p.getComponentById("searchComp_1");
    if (cptIbxName == undefined) {
        search_box.hide();
    }
    scwin.btn_search_onclick();
};

scwin.btn_search_onclick = function (e) {
    dmp_designVo.set("pageIndex", "1");
    pgl_designList.setSelectedIndex(1);
    $c.sbm.execute($p, sbm_selectDesignVoList);
};

scwin.sbm_designList_submitdone = function (e) {
    scwin.globalElData = e.responseJSON.elData; // 엑셀 다운로드를 위한 totalCount를 가지는 globalElData 전역변수 저장
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    console.log(elData);

    if (elHeader == null || elHeader == "" || elHeader == "undefiend" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    // 자동화 모드인지 확인
    if (scwin.isCompleteAutoMappingMode) {
        console.log("2단계: 전체 업무 데이터 조회 완료, 자동화 매핑 시작");
        scwin.isCompleteAutoMappingMode = false; // 플래그 리셋

        // 전체 업무 데이터 (상위업무 검색용)
        var allTasksData = elData.designVoList;
        console.log("전체 업무 데이터 건수:", allTasksData.length);

        // 현재 그리드의 데이터 (ptTaskName이 있는 실제 매핑 대상)
        var currentGridData = dlt_designVoList.getAllJSON();
        console.log("현재 그리드 데이터 건수:", currentGridData.length);

        // 매핑 실행 (그리드 데이터 + 전체 데이터)
        scwin.performCompleteAutoMappingWithFullData(currentGridData, allTasksData);

        return; // 일반 그리드 업데이트는 하지 않음
    }

    // 일반 조회 모드일 때만 그리드 업데이트
    spn_listCnt.setLabel(elData.totalCount);
    dlt_designVoList.setJSON(elData.designVoList);

    var totalPageCount = Math.ceil(elData.totalCount / dmp_designVo.get("pageSize"));
    pgl_designList.setCount(totalPageCount);
    spn_totalPageCount.setValue(totalPageCount);
    spn_pageIndex.setValue(dmp_designVo.get("pageIndex"));
    pgl_designList.setSelectedIndex(dmp_designVo.get("pageIndex"));
};

scwin.pgl_designList_onclick = function (idx) {
    dmp_designVo.set("pageIndex", idx);
    $c.sbm.execute($p, sbm_selectDesignVoList);
};

scwin.btn_reset_onclick = function (e) {
    dmp_designVo.setEmptyValue();
    dmp_designVo.set("pageIndex", "1");
    pgl_designList.setSelectedIndex(1);

    $c.sbm.execute($p, sbm_selectDesignVoList);
};

scwin.btn_add_onclick = function (e) {
    dlt_designVoList.insertRow(0);
};

scwin.btn_delete_onclick = function (e) {
    let chkArrIdx = grd_list.getCheckedIndex("chk");
    dlt_designVoList.deleteRows(chkArrIdx);
};

scwin.btn_save_onclick = function (e) {
  let reqObj = {
    "elData": {
      "designVoList": dlt_designVoList.getModifiedJSON()
    }
  };
  $c.sbm.execute($p, sbm_saveDesignVoList, reqObj);
};

scwin.sbm_saveDesignVoList_submitdone = function (e) {
  var elHeader = e.responseJSON.elHeader;
  if (elHeader == null || elHeader == "" || elHeader == "undefiend" || elHeader.resSuc == false) {
    $c.win.alert($p, `에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
    return false;
  } else {
    if (scwin.isAutoMappingUpdate) {
      // 자동 매핑 업데이트 완료
      scwin.isAutoMappingUpdate = false;
      $c.win.alert($p, "자동 매핑이 완료되었습니다!");
    } else {
      // 일반 저장 완료
      $c.win.alert($p, "저장되었습니다.");
    }
  }
  scwin.btn_search_onclick();
};


scwin.grd_list_oncellclick = function (row, col, colId) {
    if (colId === "ptTaskName") {
        scwin.openParentTaskPopup(row);
    }
};

scwin.openDetailPopup = function (rowIndex) {
    let rowData = dlt_designVoList.getRowJSON(rowIndex);

    var jsnPopupData = {
        "type": "json",
        "name": "taskData",
        "data": rowData
    };

    var options = {
        id: "task_detail_popup",
        type: "wframePopup",
        width: "750px",
        height: "700px",
        top: "30px",
        left: "200px",
        popupName: "업무 상세 정보",
        modal: true,
        closeAction: "scwin.detailPopup_closeAction",
        dataObject: jsnPopupData
    };

    $p.openPopup("/InsWebApp/ui/task/design/DesignPopup.xml", options);
};

scwin.openParentTaskPopup = function (rowIndex) {
    let rowData = dlt_designVoList.getRowJSON(rowIndex);

    var taskData = {
        currentTaskId: rowData.taskId,
        currentTaskName: rowData.taskName,
        currentRowIndex: rowIndex,
        currentStgId: rowData.stgId
    };

    var jsnPopupData = {
        "type": "json",
        "name": "taskData",
        "data": taskData
    };

    var options = {
        id: "task_tree_popup",
        type: "wframePopup",
        width: "600px",
        height: "650px",
        top: "30px",
        left: "300px",
        popupName: "업무 트리 선택",
        modal: true,
        closeAction: "scwin.taskTreePopup_closeAction",
        dataObject: jsnPopupData
    };

    $p.openPopup("/InsWebApp/ui/task/design/DesignTaskTree.xml", options);
};

// TaskTree.xml (상위 업무 선택을 위한 업무 트리) 팝업에서 받아온 데이터
scwin.receiveTaskData = function (returnData) {
    if (returnData && returnData.selectedTask) {
        var selectedTask = returnData.selectedTask;
        var currentRowIndex = returnData.currentRowIndex;

        if (currentRowIndex !== null && currentRowIndex >= 0) {
            dlt_designVoList.setCellData(currentRowIndex, "ptTaskId", selectedTask.taskId);
            dlt_designVoList.setCellData(currentRowIndex, "ptTaskName", selectedTask.taskName);
            dlt_designVoList.setCellData(currentRowIndex, "stgId", selectedTask.stgId);
            dlt_designVoList.setCellData(currentRowIndex, "taskDepth", parseInt(selectedTask.taskDepth) + 1);

            console.log(`상위업무 선택 완료: [${selectedTask.taskName}] (원본 depth: ${selectedTask.taskDepth}, 설정될 depth: ${parseInt(selectedTask.taskDepth) + 1})`);
            $c.win.alert("선택된 업무: " + selectedTask.taskName);
        }
    }
};

// 엑셀 다운로드
scwin.btn_excel_download_onclick = function (e) {
    // 전체 건수 확인
    var totalCount = scwin.globalElData ? scwin.globalElData.totalCount : 0;
    console.log("전체 데이터 건수:", totalCount);
    console.log("globalElData:", scwin.globalElData);

    if (totalCount === 0) {
        $c.win.alert("다운로드할 데이터가 없습니다.");
        return;
    }

    // 현재 페이징 조건 백업
    var originalPageIndex = dmp_designVo.get("pageIndex");
    var originalPageSize = dmp_designVo.get("pageSize");

    // 전체 데이터 조회를 위한 조건 설정
    dmp_designVo.set("pageIndex", "1");
    dmp_designVo.set("pageSize", totalCount.toString()); // 전체 건수만큼 설정

    // 전체 데이터 조회 실행
    $c.sbm.execute($p, sbm_selectDesignVoListForExcel);

    // 원래 페이징 조건 복원
    dmp_designVo.set("pageIndex", originalPageIndex);
    dmp_designVo.set("pageSize", originalPageSize);
};

// 엑셀 다운로드용 전체 데이터 조회 완료 후 처리
scwin.sbm_selectDesignVoListForExcel_submitdone = function (e) {
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (elHeader == null || elHeader == "" || elHeader == "undefined" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    // 전체 데이터가 없는 경우
    if (!elData.designVoList || elData.designVoList.length === 0) {
        $c.win.alert("다운로드할 데이터가 없습니다.");
        return;
    }

    console.log("엑셀 다운로드 실제 조회된 데이터 건수:", elData.designVoList.length);

    // 임시로 그리드에 전체 데이터 설정
    var originalData = dlt_designVoList.getAllJSON();
    dlt_designVoList.setJSON(elData.designVoList);

    // 엑셀 다운로드 실행
    var options = {
        fileName: "설계_업무_목록_" + new Date().toISOString().slice(0, 10).replace(/-/g, ""),
        // useStyle 및 headerFontBold 설정을 이용하여 GridView를 Excel 파일로 다운로드할 때 헤더 폰트를 굵게 표시
        useStyle: true,
        headerFontBold: true,
        bodyFontBold: false,
        type: 1, // inputType이 "select", "autoComplete", 혹은 "checkcombobox"인 경우 >> label 값 다운
        trim: 1,
        removeColumns: "0, 12", // 첫 번째 컬럼(체크박스)이랑 hidden 처리된 13번째 컬럼(프로젝트 ID) 제외
        processMsg: "엑셀 파일을 생성하고 있습니다...",
        timeout: 60000,
        checkInterval: 1000,
        onSuccessCallback: function () {
            $c.win.alert("엑셀 파일 다운로드가 완료되었습니다.");
            // 원래 데이터로 복원
            dlt_designVoList.setJSON(originalData);
        },
        onFailureCallback: function () {
            $c.win.alert("엑셀 파일 다운로드에 실패했습니다.");
            // 원래 데이터로 복원
            dlt_designVoList.setJSON(originalData);
        }
    };

    grd_list.advancedExcelDownload(options);
};

/**
 * 상위업무 자동설정 버튼 클릭 이벤트 
 * 저장된 모든 업무 데이터에서 상위업무명을 기반으로 자동으로 상위업무 관계를 설정
 */
scwin.btn_auto_set_parent_onclick = function (e) {
  console.log("===  완전 자동화 시작 ===");

  // 미저장 데이터가 있는지 체크
  var hasUnsavedData = false;
  for (var i = 0; i < dlt_designVoList.getRowCount(); i++) {
    var rowStatus = dlt_designVoList.getRowStatus(i);
    if (rowStatus === "C" || rowStatus === "U") {
      hasUnsavedData = true;
      break;
    }
  }

  if (hasUnsavedData) {
    $c.win.alert($p, "저장되지 않은 데이터가 있습니다.\n먼저 저장 버튼을 클릭해주세요.");
    return;
  }

  // 저장된 데이터에 대해 완전 자동설정 실행
  scwin.executeCompleteAutoMapping();
};

/**
 * 완전 자동화 실행 (모든 관계 설정)
 */
scwin.executeCompleteAutoMapping = function () {
  console.log("완전 자동화 실행 시작...");

  // 완전 자동화 모드 플래그 설정
  scwin.isCompleteAutoMappingMode = true;

  console.log("1단계: 전체 업무 데이터 조회 (상위업무 검색용)");

  // 전체 업무 데이터를 먼저 조회해서 상위업무 검색에 사용
  var originalPageIndex = dmp_designVo.get("pageIndex");
  var originalPageSize = dmp_designVo.get("pageSize");

  // 전체 데이터 조회를 위한 조건 설정
  dmp_designVo.set("pageSize", "99999");
  dmp_designVo.set("pageIndex", "1");

  var reqObj = {
    "elData": {
      "designVo": dmp_designVo.getJSON()
    }
  };

  // 전체 업무 데이터 조회 (상위업무 검색용)
  $c.sbm.execute($p, sbm_selectDesignVoList, reqObj);

  // 원래 페이징 조건 복원
  dmp_designVo.set("pageIndex", originalPageIndex);
  dmp_designVo.set("pageSize", originalPageSize);
};


// 더 이상 사용하지 않는 함수 (현재 그리드 데이터를 직접 사용)
// scwin.sbm_selectAllDesignForMapping_submitdone = function (e) { ... }

/**
 * 완전 자동화 매핑 실행 (그리드 데이터 + 전체 데이터 사용)
 * @param {Array} currentGridData 현재 그리드 데이터 (ptTaskName 포함)
 * @param {Array} allTasksData 전체 업무 데이터 (상위업무 검색용)
 */
scwin.performCompleteAutoMappingWithFullData = function (currentGridData, allTasksData) {
  console.log("===  완전 자동화 매핑 실행 (개선된 버전) ===");
  console.log("현재 그리드 데이터 개수:", currentGridData.length);
  console.log("전체 업무 데이터 개수:", allTasksData.length);

  var mappingCount = 0;
  var errorCount = 0;
  var updateList = []; // 업데이트할 데이터 목록

  // 먼저 매핑할 대상들을 수집 (현재 그리드 데이터에서)
  var mappingTargets = [];

  console.log("=== 현재 그리드 데이터에서 매핑 대상 찾기 ===");
  for (var i = 0; i < currentGridData.length; i++) {
    var task = currentGridData[i];
    var taskId = task.taskId;
    var taskName = task.taskName;
    var ptTaskName = task.ptTaskName;
    var ptTaskId = task.ptTaskId;

    console.log(`업무 ${i+1}: [${taskName}] ptTaskName="${ptTaskName}" ptTaskId="${ptTaskId}"`);

    // ptTaskName이 있고 ptTaskId가 0인 업무만 매핑 대상으로 설정
    if (ptTaskName && ptTaskName.trim() !== "" && 
        (!ptTaskId || ptTaskId === "0")) {

      console.log(`  → 매핑 대상 발견: [${taskName}] 상위업무명: "${ptTaskName}"`);

      // 전체 데이터에서 상위업무 검색
      var parentTask = scwin.findParentTaskInAllData(allTasksData, ptTaskName.trim(), taskId);
      if (parentTask) {
        console.log(`  → 상위업무 찾기 성공: [${parentTask.taskName}] (ID: ${parentTask.taskId})`);
        mappingTargets.push({
          task: task,
          parentTask: parentTask
        });
      } else {
        console.warn(`  → 상위업무를 찾을 수 없음: [${taskName}] → [${ptTaskName}]`);
        errorCount++;
      }
    } else {
      if (!ptTaskName || ptTaskName.trim() === "") {
        console.log(`  → 상위업무명 없음 (최상위 업무)`);
      } else if (ptTaskId && ptTaskId !== "0") {
        console.log(`  → 이미 관계 설정됨 (ptTaskId: ${ptTaskId})`);
      }
    }
  }

  console.log(`매핑 대상: ${mappingTargets.length}건, 에러: ${errorCount}건`);

  if (mappingTargets.length === 0) {
    $c.win.alert($p, "자동 매핑할 데이터가 없습니다.\n상위업무명이 설정된 업무가 없거나 이미 모두 매핑되어 있습니다.");
    return;
  }

  // 순서대로 매핑 처리
  for (var j = 0; j < mappingTargets.length; j++) {
    var target = mappingTargets[j];
    var currentTask = target.task;
    var parentTask = target.parentTask;
    var currentTaskId = currentTask.taskId;
    var currentTaskName = currentTask.taskName;

    console.log(`매핑 처리: [${currentTaskName}] → [${parentTask.taskName}]`);

    // 순환 참조 체크 (전체 데이터 기준)
    if (scwin.checkCircularReference(allTasksData, currentTaskId, parentTask.taskId)) {
      console.error(`순환 참조 발견: [${currentTaskName}] → [${parentTask.taskName}] 건너뜀`);
      errorCount++;
      continue;
    }

    // 상위업무의 실제 depth 계산 (전체 데이터 기준)
    var actualParentDepth = scwin.calculateActualDepth(allTasksData, parentTask.taskId);
    var newDepth = actualParentDepth + 1;

    // 업데이트할 데이터에 추가
    updateList.push({
      taskId: currentTaskId,
      ptTaskId: parentTask.taskId,
      stgId: parentTask.stgId,  // 상위업무와 동일한 stgId 설정
      taskDepth: newDepth
    });

    mappingCount++;
    console.log(`✅ 매핑 성공: [${currentTaskName}] → [${parentTask.taskName}] (ptTaskId: ${parentTask.taskId}, stgId: ${parentTask.stgId}, depth: ${newDepth})`);
  }

  console.log(`자동 매핑 완료: ${mappingCount}건 성공, ${errorCount}건 실패`);

  if (updateList.length > 0) {
    // 현재 그리드에 매핑된 결과 반영
    scwin.applyMappingToGrid(updateList);

    // 서버에 업데이트 요청
    scwin.executeAutoMappingUpdate(updateList);
  } else {
    $c.win.alert($p, "자동 매핑할 데이터가 없습니다.");
  }
};

/**
 * 업무의 실제 depth를 재귀적으로 계산
 * @param {Array} allTasksData 전체 업무 데이터
 * @param {string} taskId 계산할 업무 ID
 * @return {number} 실제 depth (1부터 시작)
 */
scwin.calculateActualDepth = function(allTasksData, taskId) {
  var task = scwin.findTaskById(allTasksData, taskId);
  if (!task) {
    console.warn(`calculateActualDepth: 업무 ${taskId}를 찾을 수 없음, depth=1 반환`);
    return 1; // 업무를 찾을 수 없으면 기본 depth
  }

  console.log(`calculateActualDepth: [${task.taskName}] taskId=${taskId}, ptTaskId=${task.ptTaskId}, 현재DB_depth=${task.taskDepth}`);

  // 상위 업무가 없으면 (최상위) depth = 1
  if (!task.ptTaskId || task.ptTaskId === "0") {
    console.log(`calculateActualDepth: [${task.taskName}] 최상위 업무, depth=1 (DB값=${task.taskDepth})`);
    return 1; // 최상위는 항상 1
  }

  // 상위 업무의 depth를 재귀적으로 계산하고 +1
  var parentDepth = scwin.calculateActualDepth(allTasksData, task.ptTaskId);
  var myDepth = parentDepth + 1;
  console.log(`calculateActualDepth: [${task.taskName}] 상위depth=${parentDepth}, 계산된depth=${myDepth} (DB값=${task.taskDepth})`);
  return myDepth;
};

/**
 * 순환 참조 체크
 * @param {Array} allTasksData 전체 업무 데이터
 * @param {string} currentTaskId 현재 업무 ID
 * @param {string} targetParentId 설정하려는 상위업무 ID
 * @return {boolean} 순환 참조 여부
 */
scwin.checkCircularReference = function(allTasksData, currentTaskId, targetParentId) {
  var visited = {};
  var checkId = targetParentId;
  var maxDepth = 10; // 무한루프 방지
  var depth = 0;

  while (checkId && checkId !== "0" && depth < maxDepth) {
    if (visited[checkId]) {
      return true; // 순환 참조 발견
    }
    if (checkId === currentTaskId) {
      return true; // 자기 자신을 상위로 설정하려고 함
    }

    visited[checkId] = true;

    // 다음 상위 업무 찾기
    var parentTask = scwin.findTaskById(allTasksData, checkId);
    checkId = parentTask ? parentTask.ptTaskId : null;
    depth++;
  }

  return false; // 순환 참조 없음
};

/**
 * ID로 업무 찾기
 * @param {Array} allTasksData 전체 업무 데이터
 * @param {string} taskId 찾을 업무 ID
 * @return {Object|null} 찾은 업무 객체
 */
scwin.findTaskById = function(allTasksData, taskId) {
  for (var i = 0; i < allTasksData.length; i++) {
    if (allTasksData[i].taskId === taskId) {
      return allTasksData[i];
    }
  }
  return null;
};

/**
 * 전체 데이터에서 상위 업무 찾기 (자기 자신 제외)
 * @param {Array} allTasksData 전체 업무 데이터 배열
 * @param {string} ptTaskName 찾을 상위업무명
 * @param {string} currentTaskId 현재 업무 ID (자기 자신 제외용)
 * @return {Object|null} 찾은 상위 업무 객체, 없으면 null 반환
 */
scwin.findParentTaskInAllData = function (allTasksData, ptTaskName, currentTaskId) {
  for (var i = 0; i < allTasksData.length; i++) {
    var task = allTasksData[i];
    if (task.taskId !== currentTaskId && task.taskName && task.taskName.trim() === ptTaskName) {
      return {
        taskId: task.taskId,
        taskName: task.taskName,
        stgId: task.stgId,
        taskDepth: task.taskDepth
      };
    }
  }
  return null;
};

/**
 * 매핑 결과를 현재 그리드에 반영
 * @param {Array} updateList 업데이트할 데이터 목록
 */
scwin.applyMappingToGrid = function (updateList) {
  console.log("그리드에 매핑 결과 반영 중...");

  for (var i = 0; i < updateList.length; i++) {
    var updateData = updateList[i];

    // 현재 그리드에서 해당 업무 찾기
    for (var j = 0; j < dlt_designVoList.getRowCount(); j++) {
      var gridTaskId = dlt_designVoList.getCellData(j, "taskId");
      if (gridTaskId === updateData.taskId) {
        // 그리드에 관계 정보 업데이트
        dlt_designVoList.setCellData(j, "ptTaskId", updateData.ptTaskId);
        dlt_designVoList.setCellData(j, "stgId", updateData.stgId);
        dlt_designVoList.setCellData(j, "taskDepth", updateData.taskDepth);

        var taskName = dlt_designVoList.getCellData(j, "taskName");
        console.log(`그리드 업데이트: [${taskName}] → ptTaskId: ${updateData.ptTaskId}, stgId: ${updateData.stgId}, depth: ${updateData.taskDepth}`);
        break;
      }
    }
  }
};

/**
 * 자동 매핑 결과를 서버에 업데이트
 * @param {Array} updateList 업데이트할 데이터 목록
 */
scwin.executeAutoMappingUpdate = function (updateList) {
  console.log("서버에 자동 매핑 결과 저장 중...");
  console.log("업데이트할 데이터:", updateList);

  // updateList의 각 항목에 rowStatus 추가
  var designVoListWithStatus = [];
  for (var i = 0; i < updateList.length; i++) {
    var updateData = updateList[i];
    designVoListWithStatus.push({
      taskId: updateData.taskId,
      ptTaskId: updateData.ptTaskId,
      stgId: updateData.stgId,
      taskDepth: updateData.taskDepth,
      rowStatus: "U"  // 업데이트 상태로 설정
    });
  }

  let reqObj = {
    "elData": {
      "designVoList": designVoListWithStatus
    }
  };

  // 자동 매핑 업데이트 플래그 설정
  scwin.isAutoMappingUpdate = true;

  $c.sbm.execute($p, sbm_saveDesignVoList, reqObj);
};

